config.transformExpression:
(
  $profile := event.value[0];
  {
    "payload": {
      "$comment": "OPC UA Machinery MachineIdentification companion specification profile",
      "$namespace": "https://opcfoundation.org/UA/Machinery/MachineIdentification/v1.0",
      "$source": {
        "gateway": "Ignition_Core",
        "provider": "Unified",
        "connection": "OPC-UA",
        "tagPath": $profile._path,
        "model": $profile._model
      },
      "$metadata": {
        "publisher": "HighByte Intelligence Hub",
        "schemaVersion": "1.0.0",
        "dataQuality": "Good",
        "profileType": "CESMII Smart Manufacturing Profile"
      },
      "timestamp": event.timestamp,
      "manufacturer": $each($profile.Manufacturer, function($v, $k) {
        { "locale": $k, "text": $v }
      }),
      "serialNumber": $profile.SerialNumber,
      "productInstanceUri": $profile.ProductInstanceUri,
      "manufacturerUri": $profile.ManufacturerUri,
      "model": $each($profile.Model, function($v, $k) {
        { "locale": $k, "text": $v }
      }),
      "productCode": $profile.ProductCode,
      "hardwareRevision": $profile.HardwareRevision,
      "softwareRevision": $profile.SoftwareRevision,
      "deviceClass": $profile.DeviceClass,
      "yearOfConstruction": $profile.YearOfConstruction,
      "monthOfConstruction": $profile.MonthOfConstruction,
      "initialOperationDate": $fromMillis($profile.InitialOperationDate),
      "assetId": $profile.AssetId,
      "componentName": $profile.ComponentName,
      "location": $profile.Location
    },
    "topic": $profile._path
  }
)
